import{_ as p,a0 as r,w as i,s as a,ao as o,I as D,x as u,a1 as e,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"每日Ubuntu小技巧 - 使用Ubuntu拷貝CD和DVD光盤 | LCTT x X-CMD","titleTemplate":false,"description":"每日Ubuntu小技巧 - 使用Ubuntu拷貝CD和DVD光盤 | LCTT (201312) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"每日Ubuntu小技巧 - 使用Ubuntu拷貝CD和DVD光盤 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"每日Ubuntu小技巧 - 使用Ubuntu拷貝CD和DVD光盤 | LCTT (201312) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201312/Daily Ubuntu Tips – Copy CD & DVD Discs Using Ubuntu","title":"每日Ubuntu小技巧 - 使用Ubuntu拷貝CD和DVD光盤","tag":"201312","desc":""},"relativePath":"201312/Daily Ubuntu Tips – Copy CD & DVD Discs Using Ubuntu.md","filePath":"[post].md"}'),l={name:"201312/Daily Ubuntu Tips – Copy CD & DVD Discs Using Ubuntu.md"};function b(d,t,C,U,g,V){const n=r("Link");return i(),a("div",null,[t[11]||(t[11]=o('<h1 id="每日ubuntu小技巧-使用ubuntu拷貝cd和dvd光盤" tabindex="-1">每日Ubuntu小技巧 - 使用Ubuntu拷貝CD和DVD光盤 <a class="header-anchor" href="#每日ubuntu小技巧-使用ubuntu拷貝cd和dvd光盤" aria-label="Permalink to “每日Ubuntu小技巧 - 使用Ubuntu拷貝CD和DVD光盤”">​</a></h1><p>Ubuntu是一個功能強大的現代操作系統，可以執行很多任務。你可以使用Ubuntu創建文檔，瀏覽網頁，聆聽音樂，以及燒錄或拷貝媒體光盤。</p><p>就像Windows和Max OS X一樣，Ubuntu是無所不能的！</p><p>這篇簡單的手冊將告訴你如何使用Ubuntu拷貝，翻錄或燒錄一張CD/DVD光盤。如果你有一張包含音頻文件（音樂）或視頻文件（電影）的光盤，並且你想要複製這張光盤（創建多個副本），使用Ubuntu會使你很容易做到。</p><p>如果你已經準備好想要拷貝進一張媒體光盤（CD/DVD）的音頻或視頻文件，Ubuntu也可以處理它。你可以在Ubuntu上安裝很多的免費軟件用於燒錄或翻錄一張CD/DVD光盤，但Ubuntu已經安裝好一款默認的相關軟件。接下來我們會使用這款默認軟件去拷貝或翻錄CD/DVD光盤。</p><p>Brasero光盤燒錄機安裝在UBuntu的每一個版本上。它是Ubuntu上默認的光盤燒錄機。它被設計得足夠簡單，擁有諸多獨特的特性來使得用户能夠快速簡便地創建光盤。</p><p>下面列出來的是Brasero的一些特性：</p><ul><li>創建數據CD/DVD時自動過濾隱藏和損壞的文件</li><li>同時支持多個會話，可以執行磁盤文件的完整性檢查</li><li>可以即時燒錄視頻CD/DVD</li><li>可以鏡像CD/DVD內容到硬盤</li><li>可以擦除可擦寫CD/DVD</li></ul><p>還有很多其它的功能。如果你想找一個Ubuntu上簡便的磁盤刻錄機，在做任何操作前請先看看這個軟件。</p><p>要開始使用Brasero去燒錄CD/DVD光盤，請確保你的電腦安裝了CD/DVD燒錄機。如果沒有，顯然你無法燒錄。如果你的電腦符合要求，將你想要翻錄的數據光盤插入CD/DVD，然後進入Dash，搜索Brasero。</p><p>當Brasero打開後，選擇磁盤拷貝。這個功能會拷貝一個光盤裏的內容，然後將其寫入到另一個光盤中。如果這是你想要的，請繼續。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/12/braseroubuntucdburner.png" alt=""></p><p>如果Ubuntu能夠訪問你的CD/DVD燒錄機，Brasero會打開並自動識別光盤內容。在這裏，你可以單擊 <strong>複製</strong> 從源光盤創建一個拷貝。如果你希望創建多個拷貝，單擊按鈕 <strong>創建多個拷貝</strong>。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/12/ubuntubraserocdburner.png" alt=""></p><p>當系統提示安裝所需的軟件包時，單擊 <strong>安裝</strong>。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/12/ubuntubraserocdburner1.png" alt=""></p><p>安裝完成後，Brasero會開始拷貝光盤。如果最終光盤完成拷貝，系統會提示你插入一張空白的可寫入的CD/DVD光盤以便寫入拷貝。插入它然後等待完成將內容寫入光盤的操作。</p><p>當你完成以上操作時，移除光盤，就可以使用燒錄好的光盤了！</p><hr>',19)),D("p",null,[t[1]||(t[1]=u("via: ",-1)),e(n,{href:"http://www.liberiangeek.net/2013/12/daily-ubuntu-tips-copy-cd-dvd-discs-using-ubuntu/"},{default:s(()=>[...t[0]||(t[0]=[u("http://www.liberiangeek.net/2013/12/daily-ubuntu-tips-copy-cd-dvd-discs-using-ubuntu/",-1)])]),_:1})]),D("p",null,[t[4]||(t[4]=u("譯者：",-1)),e(n,{href:"https://github.com/KayGuoWhu"},{default:s(()=>[...t[2]||(t[2]=[u("KayGuoWhu",-1)])]),_:1}),t[5]||(t[5]=u(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:s(()=>[...t[3]||(t[3]=[u("wxy",-1)])]),_:1})]),D("p",null,[t[8]||(t[8]=u("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[6]||(t[6]=[u("LCTT",-1)])]),_:1}),t[9]||(t[9]=u(" 原創翻譯，",-1)),e(n,{href:"http://linux.cn/"},{default:s(()=>[...t[7]||(t[7]=[u("Linux中國",-1)])]),_:1}),t[10]||(t[10]=u(" 榮譽推出",-1))])])}const f=p(l,[["render",b]]);export{w as __pageData,f as default};
